def emp_lip(f, n):
    h=1.0/n; best=0.0; prev=f(0.0)
    for i in range(1,n+1):
        cur=f(i*h); best=max(best, abs(cur-prev)/h); prev=cur
    return best
for k in range(1,9):
    L = emp_lip(lambda x: tent_iterate(k,x), 2**(k+12))
    print(k, 2**k, round(L,2), tent_iterate(k,0.0), tent_iterate(k,0.5**k))

