def crossings(samples, level=0.5):
    c=0; prev=samples[0]-level
    for s in samples[1:]:
        cur=s-level
        if prev==0: prev=cur; continue
        if cur==0 or (prev<0)!=(cur<0): c+=1
        prev=cur
    return c
for k in range(1,8):
    n=200*2**k
    s=[tent_iterate(k, i/n) for i in range(n+1)]
    print('k=',k,'crossings=',crossings(s),' 2^k=',2**k)

